/**
 * Global registry of contextual welcome headlines. A host surface (e.g. a scene with the AI panel
 * integration) registers headlines that fit what the user is looking at, and the composer's empty
 * state picks from them instead of the generic defaults while the provider stays registered.
 */
export const welcomeOverrideLogic = kea<welcomeOverrideLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'welcomeOverrideLogic']),

    actions({
        /** Idempotent upsert — re-register the same `providerId` to update its headlines. */
        registerHeadlines: (providerId: string, headlines: string[]) => ({ providerId, headlines }),
        deregisterHeadlines: (providerId: string) => ({ providerId }),
    }),

    reducers({
        providers: [
            {} as Record<string, string[]>,
            {
                registerHeadlines: (state, { providerId, headlines }) => ({ ...state, [providerId]: headlines }),
                deregisterHeadlines: (state, { providerId }) => {
                    if (!(providerId in state)) {
                        return state
                    }
                    const { [providerId]: _dropped, ...rest } = state
                    return rest
                },
            },
        ],
    }),

    selectors({
        // First registered provider with headlines wins (object insertion order) — mirrors the
        // first-writer-wins convention of `attachedContextLogic`.
        overrideHeadlines: [
            (s) => [s.providers],
            (providers: Record<string, string[]>): string[] | null =>
                Object.values(providers).find((headlines) => headlines.length > 0) ?? null,
        ],
    }),
])
